Definition CS_MS27 : csite := mk_csite MEMSET27_P0 MEMSET27_Q KEEPK [] (MSV 608 27).
Definition XMS : Z * xaction := (0x60650, XCallKs [CS_MS32; CS_MS27]).
Definition XF11 : Z * xaction := (0x60650, XHand (hx_fold 0x60650 11)).
Definition RET1 : list Z := [0x99a74; 0x99c40; 0x99f10; 0x9a0d0; 0x9a204; 0x9a384; 0x9a768; 0x9b344; 0x9b384].
Definition RET2 : list Z := [0x99a84; 0x99c50; 0x99f20; 0x9a0e0; 0x9a214; 0x9a394; 0x9a778; 0x9b354; 0x9b394].
Definition XF10 : Z * xaction := (0x9b51c, XHand (hx_fold 0x9b51c 10)).
Definition DCFVf : list (vop * Z * rkind) :=
  [(VCopy 0, 0, RT); (VCopy 1, 0, RZ); (VSub 4 1136, 2768, RW); (VSub 41 178, 345, RZ); (VSub 20 32, 984, RW); (VCopy 23, 0, RW);
   (VCopy 15, 0, RW); (VCopy 16, 0, RZ); (VCopy 17, 0, RZ); (VCopy 18, 0, RZ); (VCopy 19, 0, RW); (VCopy 21, 0, RW); (VCopy 22, 0, RW);
