   (VCopy 7, 0, RW)] ++ List.map (fun i => (VCopy i, 0, RW)) (seq 30 11) ++
  [(VCopy 13, 0, RO); (VCopy 14, 0, RO); (VCopy 6, 0, RO); (VCopy 43, 0, RZ); (VCopy 44, 0, RZ); (VSub 45 80, 8, RW)].
Definition CS_DCFf (frac : bool) : csite := mk_csite (DCF_P0f frac) (DCF_Qf frac) KEEPFK [] DCFVf.
Definition SSV : list (vop * Z * rkind) := [(VSub 4 3840, 64, RW); (VCopy 23, 0, RW); (VCopy 13, 0, RO); (VCopy 14, 0, RO)].
Definition CS_SSF5 : csite := mk_csite SSF5_P0 SSF5_Q KEEPK [] SSV.
Definition NODES1 : list (Z * xaction) :=
  [(0x4ad74, XCallK CS_SM4); XNJ 0x9964c]
  ++ ([XF11; XMS] ++ List.map XNJ RET1 ++ [XF11; XMS] ++ List.map XNJ RET2)
  ++ [(0x99a8c, XHand H_INT_F); XNJ 0x99c60; (0x99c64, XHand H_DOT_F);
      (0x99e00, XHand R_NOFRAC_F); XNJ 0x99e00; XNJ 0x99c88; (0x99cac, XHand R_DIG0_F); XNJ 0x99cac;
