      (0x9a36c, XHand R_FRAC_F); XNJ 0x9a36c;
      XNFR 0x99e48; XNFR 0x99ecc; XNFR 0x9a16c; XNLF 0x9a1a4; XNFR 0x9a1f0; XNFR 0x9a104; XNFR 0x9a3c4]
  ++ ([XF11; XMS] ++ List.map XNJ RET1 ++ [XF11; XMS] ++ List.map XNJ RET2).
Definition NODES5 : list (Z * xaction) :=
  [(0x9a3dc, XHand H_TM_F); XF10; XNAF 0x9b51c;
   XNTF 0x9a784; XNTKF 0x9a814 [26]; XNTF 0x9accc; XNTKF 0x9ac0c [26]; XNTF 0x9a790; XNTF 0x9a84c; XNTF 0x9a9b8; XNK1 0x9aa24;
