Definition NODESC : list (Z * xaction) := xconst NODES GD.
Lemma NODESC_xsites : xsites NODESC = xsites NODES. Proof. exact (xconst_xsites NODES GD). Qed.
Lemma NODESC_xksites : xksites NODESC = xksites NODES. Proof. exact (xconst_xksites NODES GD). Qed.
Lemma NODESC_xfsites : xfsites NODESC = xfsites NODES. Proof. exact (xconst_xfsites NODES GD). Qed.
Lemma NODESC_xhandl : xhandl NODESC = xhandl NODES. Proof. exact (xconst_xhandl NODES GD). Qed.
From Ltac2 Require Import Ltac2 Constr Std Control.
Ltac2 cert_refl_vm (rhs : constr) :=
  let g := Control.goal () in
  let r := constr:(@eq_refl _ $rhs) in
  Std.exact_no_check (Constr.Unsafe.make (Constr.Unsafe.Cast r Constr.Cast.vm g)).
Set Default Proof Mode "Ltac2".
Lemma SPF_cert : (match wstartx TM IMGW (vars_below (s_next P0)) 10 P0 P0RUN NODESC with
                  | Some l => forallb (fun X => fin_q SPF_Q RETS (s_next P0) (xs_st X)) l | None => false end) = true.
Proof. cert_refl_vm constr:(true). Qed.
Set Default Proof Mode "Classic".
